class _PigeonCodec extends StandardMessageCodec {
  const _PigeonCodec();
  @override
  void writeValue(WriteBuffer buffer, Object? value) {
    if (value is int) {
      buffer.putUint8(4);
      buffer.putInt64(value);
    } else if (value is ObdBackgroundRecordingCapabilityMessage) {
      buffer.putUint8(129);
      writeValue(buffer, value.index);
    } else if (value is ObdPermissionStatusMessage) {
      buffer.putUint8(130);
      writeValue(buffer, value.index);
    } else if (value is ObdLinkStateValueMessage) {
      buffer.putUint8(131);
      writeValue(buffer, value.index);
    } else if (value is ObdLinkFailureMessage) {
      buffer.putUint8(132);
      writeValue(buffer, value.index);
    } else if (value is ObdConsecutiveFailuresPolicyMessage) {
      buffer.putUint8(133);
      writeValue(buffer, value.index);
    } else if (value is ObdTransportStatusMessage) {
      buffer.putUint8(134);
      writeValue(buffer, value.index);
    } else if (value is ObdRecordingStateValueMessage) {
      buffer.putUint8(135);
      writeValue(buffer, value.index);
    } else if (value is ObdOneShotEnqueueResultMessage) {
      buffer.putUint8(136);
      writeValue(buffer, value.index);
    } else if (value is ObdCapabilitiesMessage) {
      buffer.putUint8(137);
      writeValue(buffer, value.encode());
    } else if (value is ObdAdapterMessage) {
      buffer.putUint8(138);
      writeValue(buffer, value.encode());
    } else if (value is ObdLinkStateMessage) {
      buffer.putUint8(139);
      writeValue(buffer, value.encode());
    } else if (value is ObdModuleMessage) {
      buffer.putUint8(140);
      writeValue(buffer, value.encode());
    } else if (value is ObdStepMessage) {
      buffer.putUint8(141);
      writeValue(buffer, value.encode());
    } else if (value is ObdLimitsMessage) {
      buffer.putUint8(142);
      writeValue(buffer, value.encode());
    } else if (value is ObdPlanMessage) {
      buffer.putUint8(143);
      writeValue(buffer, value.encode());
    } else if (value is ObdSignalExchangeMessage) {
      buffer.putUint8(144);
      writeValue(buffer, value.encode());
    } else if (value is ObdLiveStateMessage) {
      buffer.putUint8(145);
      writeValue(buffer, value.encode());
    } else if (value is ObdRecordingNotificationMessage) {
      buffer.putUint8(146);
      writeValue(buffer, value.encode());
    } else if (value is ObdBridgeConfigMessage) {
      buffer.putUint8(147);
      writeValue(buffer, value.encode());
    } else if (value is ObdRecordingOptionsMessage) {
      buffer.putUint8(148);
      writeValue(buffer, value.encode());
    } else if (value is ObdStartRecordingRequest) {
      buffer.putUint8(149);
      writeValue(buffer, value.encode());
    } else if (value is ObdRecordingStateMessage) {
      buffer.putUint8(150);
      writeValue(buffer, value.encode());
    } else if (value is ObdCompanionStatusMessage) {
      buffer.putUint8(151);
      writeValue(buffer, value.encode());
    } else if (value is ObdAutoSessionMessage) {
      buffer.putUint8(152);
      writeValue(buffer, value.encode());
    } else {
      super.writeValue(buffer, value);
    }
  }

  @override
  Object? readValueOfType(int type, ReadBuffer buffer) {
    switch (type) {
      case 129:
        final value = readValue(buffer) as int?;
        return value == null
            ? null
            : ObdBackgroundRecordingCapabilityMessage.values[value];
      case 130:
        final value = readValue(buffer) as int?;
        return value == null ? null : ObdPermissionStatusMessage.values[value];
      case 131:
        final value = readValue(buffer) as int?;
        return value == null ? null : ObdLinkStateValueMessage.values[value];
      case 132:
        final value = readValue(buffer) as int?;
        return value == null ? null : ObdLinkFailureMessage.values[value];
      case 133:
        final value = readValue(buffer) as int?;
        return value == null
            ? null
            : ObdConsecutiveFailuresPolicyMessage.values[value];
      case 134:
        final value = readValue(buffer) as int?;
        return value == null ? null : ObdTransportStatusMessage.values[value];
      case 135:
        final value = readValue(buffer) as int?;
        return value == null
            ? null
            : ObdRecordingStateValueMessage.values[value];
      case 136:
        final value = readValue(buffer) as int?;
        return value == null
            ? null
            : ObdOneShotEnqueueResultMessage.values[value];
      case 137:
        return ObdCapabilitiesMessage.decode(readValue(buffer)!);
      case 138:
        return ObdAdapterMessage.decode(readValue(buffer)!);
      case 139:
        return ObdLinkStateMessage.decode(readValue(buffer)!);
      case 140:
        return ObdModuleMessage.decode(readValue(buffer)!);
      case 141:
        return ObdStepMessage.decode(readValue(buffer)!);
      case 142:
        return ObdLimitsMessage.decode(readValue(buffer)!);
      case 143:
        return ObdPlanMessage.decode(readValue(buffer)!);
      case 144:
        return ObdSignalExchangeMessage.decode(readValue(buffer)!);
      case 145:
        return ObdLiveStateMessage.decode(readValue(buffer)!);
      case 146:
        return ObdRecordingNotificationMessage.decode(readValue(buffer)!);
      case 147:
        return ObdBridgeConfigMessage.decode(readValue(buffer)!);
      case 148:
        return ObdRecordingOptionsMessage.decode(readValue(buffer)!);
      case 149:
        return ObdStartRecordingRequest.decode(readValue(buffer)!);
      case 150:
        return ObdRecordingStateMessage.decode(readValue(buffer)!);
      case 151:
        return ObdCompanionStatusMessage.decode(readValue(buffer)!);
      case 152:
        return ObdAutoSessionMessage.decode(readValue(buffer)!);
      default:
        return super.readValueOfType(type, buffer);
    }
  }
}

/// Host API implemented in Kotlin (Android). Every method is total: it
/// resolves a value, never throws across the channel. Android's
/// implementation is `ObdApi.kt`, backed by one shared instance owning a
/// `CxBleClient` and a `CxCommandSession` — not recreated per Flutter page,
/// so a live view and a later recording page share one connection rather
/// than opening a second GATT client.
class NativeObdApi {
  /// Constructor for [NativeObdApi].  The [binaryMessenger] named argument is
  /// available for dependency injection.  If it is left null, the default
  /// BinaryMessenger will be used which routes to the host platform.
  NativeObdApi({
    BinaryMessenger? binaryMessenger,
    String messageChannelSuffix = '',
  }) : pigeonVar_binaryMessenger = binaryMessenger,
       pigeonVar_messageChannelSuffix = messageChannelSuffix.isNotEmpty
           ? '.$messageChannelSuffix'
